import re

from ansible.module_utils.six.moves import configparser
from ansible.plugins.lookup.ini import LookupModule

import pytest


class FakeConfigParser(object):
    """Minimal stub mimicking the configparser API used by get_value."""

    def __init__(self, items=None, raises_no_option=False):
        self._items = items or {}
        self.raises_no_option = raises_no_option

    def items(self, section):
        return list(self._items.items())

    def get(self, section, key):
        if self.raises_no_option:
            raise configparser.NoOptionError(section, key)
        return self._items[key]


